        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_lower < var:sol_country_class_score_min_lower } set_variable = { name = sol_country_class_score_min_lower value = scope:sol_demand_cached_location.var:sol_location_demand_score_lower } }",
        "\t\tif = { limit = { scope:sol_demand_cached_location.var:sol_location_demand_score_lower > var:sol_country_class_score_max_lower } set_variable = { name = sol_country_class_score_max_lower value = scope:sol_demand_cached_location.var:sol_location_demand_score_lower } }",
