        "\tif = { limit = { var:sol_country_class_target_base > 0.00001 } set_variable = { name = sol_country_class_base_deviation_$class$ value = { value = var:sol_country_class_base_total_$class$ subtract = var:sol_country_class_target_base divide = var:sol_country_class_target_base } } }",
