        "\t\tset_variable = { name = sol_country_class_score_clergy_$class$ value = { value = var:sol_country_class_base_spending_clergy_$class$ divide = var:sol_country_class_base_total_$class$ subtract = var:sol_country_share_clergy divide = var:sol_country_class_normalizer_clergy } }",
