def emit_section_60_full_refresh(writer: ScriptWriter) -> None:
    writer.extend([
        "gls_full_refresh_country = {",
        "\t# root = country. sol_update_local_pop_demand_modifiers already refreshes",
        "\t# gls_savings_pressure_adjustment, so gls_compute_panel_display would be redundant here.",
        "\tsol_update_estate_building_maintenance = yes",
        "\tset_variable = { name = sol_estate_building_maintenance_initialized value = 1 }",
        "\tsol_update_local_pop_demand_modifiers = yes",
        "\tgls_accumulate_panel_stats = yes",
        "}",
        "",
        "gls_recalculate_global_living_standard = {",
        "\t# World scope: refresh market maps once, then refresh all countries.",
        "\tsol_refresh_market_pop_demand_maps = yes",
        "\tevery_country = { if = { limit = { total_population > 0 } gls_full_refresh_country = yes } }",
        "}",
    ])

STATIC_EMITTERS: Sequence[tuple[str, Callable[[ScriptWriter], None]]] = (
    ("01_stable_gold_transfer_scaling", emit_section_01_stable_gold_transfer_scaling),
    ("10_standard_of_living_prelude", emit_section_10_standard_of_living_prelude),
    ("20_location_pop_demand", emit_section_20_location_pop_demand),
    ("30_country_demand_math", emit_section_30_country_demand_math),
    ("31_country_demand_diagnostics", emit_section_31_country_demand_diagnostics),
    ("32_country_demand_driver", emit_section_32_country_demand_driver),
    ("40_country_update_and_map", emit_section_40_country_update_and_map),
    ("50_panel_stats_stable", emit_section_50_panel_stats_stable),
    ("50_panel_stats_standalone", emit_section_50_panel_stats_standalone),
    ("60_full_refresh", emit_section_60_full_refresh),
)


def render_static_sections(target: str, refresh_block: str) -> str:
    if target not in {"stable", "sol_standalone"}:
        raise ValueError(f"Unknown target: {target}")

    sections: list[str] = []
    for name, emitter in STATIC_EMITTERS:
        if name == "01_stable_gold_transfer_scaling" and target != "stable":
            continue
        if name == "50_panel_stats_stable" and target != "stable":
            continue
        if name == "50_panel_stats_standalone" and target != "sol_standalone":
            continue
        section_writer = ScriptWriter()
        emitter(section_writer)
        sections.append(section_writer.render().rstrip())
        if name == "10_standard_of_living_prelude":
            sections.append(refresh_block.strip())
    return "\n\n".join(sections).rstrip() + "\n"
